package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.service.notification.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
/** Focused six-area checks. Synthetic views/SMS/notification only; no communications. */
public final class SixRefinementTests extends Instrumentation {
 int checks;Activity page;PowerManager.WakeLock wake;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 Object get(Object o,String name)throws Exception{for(Class<?> t=o.getClass();t!=null;t=t.getSuperclass())try{Field f=t.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException n){}throw new NoSuchFieldException(name);}
 void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 Object call(Object o,String name,Class<?>[] types,Object... args)throws Exception{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
 void ui(final Runnable r){final Throwable[] fail={null};runOnMainSync(new Runnable(){public void run(){try{r.run();}catch(Throwable t){fail[0]=t;}}});if(fail[0]!=null)throw new RuntimeException(fail[0]);}
 Activity open(Class<?> cls,Intent intent){Activity a=startActivitySync(intent==null?new Intent(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK):intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();SystemClock.sleep(150);return a;}
 void close(){if(page!=null){final Activity a=page;ui(new Runnable(){public void run(){KeypadDialog d=KeypadDialog.current();if(d!=null)d.dismiss();a.finish();}});page=null;}}
 void key(KeypadDialog d,int code){d.onKeyDown(code,new KeyEvent(0,code));d.onKeyUp(code,new KeyEvent(1,code));}
 public void onCreate(Bundle b){start();}
 public void onStart(){Bundle out=new Bundle();final Context c=getTargetContext();try{wake=((PowerManager)c.getSystemService(Context.POWER_SERVICE)).newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK|PowerManager.ACQUIRE_CAUSES_WAKEUP,"Leo:LocalUiChecks");wake.acquire(120000);
 int flags=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;check(SystemChrome.darkFlags(flags)==View.SYSTEM_UI_FLAG_FULLSCREEN,"dark native icons preserve fullscreen policy");check(SystemChrome.volte()==(ImsStatus.registered(0)||ImsStatus.registered(1)),"VoLTE uses live registration checks");
 UiListMemory memory=new UiListMemory();ArrayList<String> rows=new ArrayList<>(Arrays.asList("a","b","c"));memory.remember("fixture",rows,1,12);UiListMemory.Entry e=memory.restore("fixture",Arrays.asList("c","a","b"));check(e!=null&&e.index==2&&e.top==12,"bookmark follows stable row after reordering");check(memory.restore("fixture",Arrays.asList("other"))==null,"removed row does not steal selection");for(int i=0;i<40;i++)memory.remember("page"+i,rows,0,0);check(memory.size()==24,"bounded in-memory bookmarks");
 check(UiText.row("Title\none\n two\tthree").equals("Title\none two three"),"secondary text stays on one logical line");String emoji=UiText.preview("A🙂BCDE",4);check(emoji.codePointCount(0,emoji.length())==4&&!Character.isHighSurrogate(emoji.charAt(emoji.length()-1)),"emoji preview has intact code points");check(UiText.preview(null,10).isEmpty()&&UiText.preview("abc",0).isEmpty(),"empty preview bounds");check(NotificationsActivity.limited("🙂🙂🙂",2).equals("🙂🙂…"),"notification limits preserve emoji");check(NotificationsActivity.limited(new String(new char[600]).replace('\0','x'),4096).length()==600,"details do not truncate at list-preview limit");
 check(HomeContext.priority(true,true,true,true,true)==5,"unread priority");check(HomeContext.priority(false,true,true,true,true)==2,"current media priority");check(HomeContext.priority(false,false,true,true,true)==5,"actionable notices priority");check(HomeContext.priority(false,false,false,true,true)==1,"next alarm priority");check(HomeContext.priority(false,false,false,false,true)==0&&HomeContext.priority(false,false,false,false,false)==-1,"fresh weather fallback and empty Home");check(HomeContext.unreadLabel(0,0).isEmpty()&&!HomeContext.unreadLabel(1,0).contains("0"),"zero unread counters hidden");check(BackupEngine.allowed("appearance","home-contextual","boolean"),"contextual mode included in backup");
 page=open(AndroidControlsActivity.class,null);final LeoActivity view=(LeoActivity)page;final ArrayList<String> list=new ArrayList<>();for(int i=0;i<50;i++)list.add("Local row "+i+"\nSecondary text");ui(new Runnable(){public void run(){view.list("Local bookmark fixture",list,0,new LeoActivity.Choice(){public void pick(int at){}},"",null);}});waitForIdleSync();SystemClock.sleep(150);ui(new Runnable(){public void run(){try{((ListView)get(view,"activeList")).setSelectionFromTop(15,12);}catch(Exception x){throw new RuntimeException(x);}}});waitForIdleSync();SystemClock.sleep(150);final int[] top={0};ui(new Runnable(){public void run(){try{ListView live=(ListView)get(view,"activeList");check(live.getSelectedItemPosition()==15,"fixture cursor positioned");top[0]=live.getSelectedView().getTop();view.begin("Local detail");view.footer("","", "Back");view.list("Local bookmark fixture",list,0,new LeoActivity.Choice(){public void pick(int at){}},"",null);}catch(Exception x){throw new RuntimeException(x);}}});waitForIdleSync();SystemClock.sleep(150);ui(new Runnable(){public void run(){try{ListView live=(ListView)get(view,"activeList");check(live.getSelectedItemPosition()==15,"Back restores selection");check(Math.abs(live.getSelectedView().getTop()-top[0])<=2,"Back restores viewport offset");view.list("Local bookmark fixture",list,3,new LeoActivity.Choice(){public void pick(int at){}},"",null);check(((ListView)get(view,"activeList")).getSelectedItemPosition()==3,"explicit nondefault navigation overrides bookmark");final int[] retried={0};view.errorPage("Local error","Local retry fixture",new Runnable(){public void run(){retried[0]++;}});view.left.run();check(retried[0]==1,"error state offers retry");view.loading("Local loading");check(view.root.getChildCount()>=3,"loading state visible");check(view.getWindow().getStatusBarColor()==view.palette.bar&&(view.getWindow().getDecorView().getSystemUiVisibility()&View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR)==0,"shared status colour and readable icons");}catch(Exception x){throw new RuntimeException(x);}}});close();
 page=open(ContactsActivity.class,null);final ContactsActivity contacts=(ContactsActivity)page;ui(new Runnable(){public void run(){try{Class<?> type=Class.forName("ro.leo.visual.ContactsActivity$Entry");Constructor<?> ctor=type.getDeclaredConstructor();ctor.setAccessible(true);Object entry=ctor.newInstance();set(entry,"name","Leo local fixture");set(entry,"number","0123456789");set(entry,"contact",-1L);set(entry,"raw",-1L);call(contacts,"detail",new Class<?>[]{type},entry);check(((List<?>)get(contacts,"listRows")).size()==5,"five main contact actions");call(contacts,"moreContact",new Class<?>[]{type},entry);KeypadDialog d=KeypadDialog.current();check(d!=null&&((String[])get(d,"items")).length==7,"advanced contact actions retained");d.dismiss();}catch(Exception x){throw new RuntimeException(x);}}});close();
 page=open(MessagesActivity.class,new Intent(c,MessagesActivity.class).putExtra("preview",true));final MessagesActivity sms=(MessagesActivity)page;ui(new Runnable(){public void run(){try{sms.left.run();KeypadDialog d=KeypadDialog.current();check(d!=null&&((String[])get(d,"items")).length==5,"five main conversation actions");for(int i=0;i<4;i++)key(d,KeyEvent.KEYCODE_DPAD_DOWN);key(d,KeyEvent.KEYCODE_DPAD_CENTER);KeypadDialog more=KeypadDialog.current();check(more!=null&&((String[])get(more,"items")).length==9,"advanced SMS actions retained");more.dismiss();}catch(Exception x){throw new RuntimeException(x);}}});close();
 page=open(PhoneActivity.class,null);final PhoneActivity phone=(PhoneActivity)page;ui(new Runnable(){public void run(){try{check(((LinearLayout)get(phone,"tabBar")).getChildCount()==3,"phone tabs retained");TextView[] chips=(TextView[])get(phone,"simChips");check(chips[0].getCompoundDrawables()[0]!=null&&chips[1].getCompoundDrawables()[0]!=null,"both SIM identities have icons");check(((EditText)get(phone,"number")).getLayout()!=null&&((EditText)get(phone,"number")).getLayout().getParagraphDirection(0)==1,"phone number direction stable");}catch(Exception x){throw new RuntimeException(x);}}});close();
 check(HomeContext.read(c,System.currentTimeMillis()).length<=1,"automatic Home has at most one card");close();out.putString("result","PASS "+checks+" six-area UI checks");
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));}finally{close();if(wake!=null&&wake.isHeld())wake.release();}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
